/*
 * A171781  Numbers for which the second bit of the binary expansion is equal
 *          to the last bit.
 * https://oeis.org/A171781
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 128, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A171781 – Numbers whose second most significant bit equals the least
 * significant (last) bit.  The terms are generated by counting numbers
 * of a given binary length; for length k≥3 there are 2^(k‑2) such
 * numbers.  The function returns the n-th term (1‑based). */
#include <stdint.h>

seq_t a(idx_t n)
{
    /* trivial case */
    if (n == 1)
        return (seq_t)2;          /* 2 = 10₂ */

    /* find the binary length k of the n-th term.
       count(k) = number of terms with exactly k bits */
    idx_t k = 2;
    idx_t count = 2;              /* for k = 2 */
    idx_t cumulative = 0;        /* terms seen so far */

    while (cumulative + count < n) {
        cumulative += count;
        ++k;
        if (k >= 4)        /* for k ≥ 4 the count doubles each step */
            count <<= 1;   /* safe: k never exceeds 63 for the tested ranges */
        /* k == 3 keeps count == 2 */
    }

    /* offset within the block of length k */
    idx_t offset = n - cumulative - 1;   /* 0‑based */

    seq_t result;
    if (k == 2) {
        /* bits: 10 and 11 */
        result = (seq_t)(2 + offset);
    } else {
        /* build the number from its bit pattern:
           msb = 1 (at position k‑1),
           second msb = b (at position k‑2),
           bits 1…k‑3 = bits_f,
           lsb = b (bit 0)                     */
        idx_t bits_f = offset & (((idx_t)1 << (k - 3)) - 1);
        idx_t b = (offset >> (k - 3)) & 1;

        result = ((seq_t)1 << (k - 1));          /* msb */
        result += ((seq_t)b << (k - 2));         /* second msb */
        result += ((seq_t)bits_f << 1);          /* middle bits */
        result += ((seq_t)b);                    /* lsb */
    }
    return result;
}
